import java.io.*;
import java.util.*;

public class P1152D_v5 {
    private static final int MODULO = 1000000007;
    private static int m;
    private static int[][] memo;

    public static void main(String[] args) {
        SimpleScanner scanner = new SimpleScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        int n = scanner.nextInt();
        m = 2 * n;
        memo = new int[m + 1][m + 2];
        for (int[] row : memo) Arrays.fill(row, -1);
        memo[0][0] = 1;
        for (int i = 1; i <= m; ++i) {
            for (int j = 0; j <= m + 1; ++j) {
                compute(i, j);
            }
        }
        int ans = 0;
        for (int i = 1; i <= m; i += 2) {
            for (int j = 1; i + j <= m; j += 2) {
                ans = (ans + memo[i][j]) % MODULO;
            }
        }
        writer.println(ans);
        writer.close();
    }

    private static int compute(int i, int j) {
        if (i < 0 || j < 0 || j > m + 1) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        if (i == 0) {
            memo[i][j] = (j == 0) ? 1 : 0;
            return memo[i][j];
        }
        if (j == 0) {
            memo[i][j] = compute(i - 1, 1);
        } else {
            memo[i][j] = (compute(i - 1, j - 1) + compute(i - 1, j + 1)) % MODULO;
        }
        return memo[i][j];
    }

    private static class SimpleScanner {
        private static final int BUFFER_SIZE = 10240;
        private Readable in;
        private CharBuffer buffer;
        private boolean eof;

        SimpleScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
            buffer = CharBuffer.allocate(BUFFER_SIZE);
            buffer.limit(0);
            eof = false;
        }

        private char read() {
            if (!buffer.hasRemaining()) {
                buffer.clear();
                int n;
                try {
                    n = in.read(buffer);
                } catch (IOException e) {
                    n = -1;
                }
                if (n <= 0) {
                    eof = true;
                    return '\0';
                }
                buffer.flip();
            }
            return buffer.get();
        }

        void checkEof() {
            if (eof)
                throw new NoSuchElementException();
        }

        char nextChar() {
            checkEof();
            char b = read();
            checkEof();
            return b;
        }

        String next() {
            char b;
            do {
                b = read();
                checkEof();
            } while (Character.isWhitespace(b));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append(b);
                b = read();
            } while (!eof && !Character.isWhitespace(b));
            return sb.toString();
        }

        int nextInt() {
            return Integer.valueOf(next());
        }

        long nextLong() {
            return Long.valueOf(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}
